// Helper to convert master data array rows into full PSP objects
const startId = 9;
MASTER_DATA.forEach((row, idx) => {
  const [drug, mfr, conds, specialty, tier, program, phone, url, copayUrl, costNote, eligibility, services, notes] = row;
  PSP_DATABASE.push({
    id: startId + idx,
    drugName: drug,
    manufacturer: mfr,
    conditions: conds,
    specialty: specialty,
    tier: tier,
    programName: program,
    eligibility: eligibility,
    costNote: costNote,
    enrollmentSteps: buildEnroll(phone, url),
    supportServices: services,
    phone: phone,
    hours: "Mon-Fri 8am-8pm ET",
    enrollmentUrl: url,
    copayUrl: copayUrl,
    faqs: notes
      ? [...baseFaq(program, drug), { q: "Anything special about this program?", a: notes }]
      : baseFaq(program, drug),
  });
});

export default PSP_DATABASE;
